// Package device is the center's devices and installations (AF-CTR-03; ArcForges-Design AD-0021 section 7): one device per node,
// phone and browser installation of an account, and one installation per device and product. A native installation keeps the
// client's ID, which is global: an ID that belongs to another account or was revoked is refused. A browser installation's ID is
// generated by the center; the browser's claimed ID is kept beside it, unique per account over live rows, so a claim never links
// two accounts. Revocation (and its cascade) arrives with AF-CTR-03's second part.
package device

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"

	"github.com/ArcForges/Cloud/center/internal/arc"
	"github.com/ArcForges/Cloud/center/internal/page"
	"github.com/ArcForges/Cloud/center/internal/platform"
	"github.com/ArcForges/Cloud/center/internal/store"
)

// Platform is a device's platform (device.platform).
type Platform int16

// The platforms.
const (
	PlatformWindows Platform = 1
	PlatformMacOS   Platform = 2
	PlatformLinux   Platform = 3
	PlatformAndroid Platform = 4
	PlatformIOS     Platform = 5
	PlatformWeb     Platform = 6
)

// String is the platform's name in a DeviceView.
func (p Platform) String() string {
	switch p {
	case PlatformWindows:
		return "windows"
	case PlatformMacOS:
		return "macos"
	case PlatformLinux:
		return "linux"
	case PlatformAndroid:
		return "android"
	case PlatformIOS:
		return "ios"
	case PlatformWeb:
		return "web"
	}
	return "unknown"
}

// Trust levels (device.trust_level).
const (
	TrustUntrusted int16 = 1
	TrustTrusted   int16 = 2
	TrustRevoked   int16 = 3
)

// The installation products (the contract's product values; DC-05).
const (
	ProductNode   = "arcforges-node"
	ProductMobile = "arcforges-mobile"
	ProductWeb    = "arcforges-web"
)

// Claim is a native client's installation claim (the contract's InstallationClaim).
type Claim struct {
	InstallationID platform.ID
	Product        string
	Platform       string
	AppVersion     string
}

func isClaimText(text string) bool {
	if len(text) < 1 || len(text) > 128 {
		return false
	}
	for index := range len(text) {
		c := text[index]
		if !(c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || strings.IndexByte("._:/-", c) >= 0) {
			return false
		}
	}
	return true
}

// MobilePlatform is the platform of a phone's claimed platform text: its leading letters name Android or iOS (for example
// "android-15" or "ios/18.1"); anything else is not a phone.
func MobilePlatform(text string) (Platform, bool) {
	end := 0
	for end < len(text) && (text[end] >= 'a' && text[end] <= 'z' || text[end] >= 'A' && text[end] <= 'Z') {
		end++
	}
	switch strings.ToLower(text[:end]) {
	case "android":
		return PlatformAndroid, true
	case "ios", "ipados":
		return PlatformIOS, true
	}
	return 0, false
}

// ValidateNativeClaim checks the claim of a native account sign-in: the contract's text rules, the product arcforges-mobile (the
// only native client that signs in to an account here; nodes enroll with AF-CTR-04) and a phone platform. The field paths are the
// request's.
func ValidateNativeClaim(claim Claim, present bool) *arc.Refusal {
	switch {
	case !present:
		return arc.InvalidArgument("installation", "required")
	case claim.InstallationID == platform.ID{}:
		return arc.InvalidArgument("installation.installation_id", "required")
	case !isClaimText(claim.Product):
		return arc.InvalidArgument("installation.product", "pattern")
	case claim.Product != ProductMobile:
		return arc.InvalidArgument("installation.product", "not_admitted")
	case !isClaimText(claim.Platform):
		return arc.InvalidArgument("installation.platform", "pattern")
	case !isClaimText(claim.AppVersion):
		return arc.InvalidArgument("installation.app_version", "pattern")
	}
	if _, ok := MobilePlatform(claim.Platform); !ok {
		return arc.InvalidArgument("installation.platform", "not_admitted")
	}
	return nil
}

func defaultName(platform Platform) string {
	switch platform {
	case PlatformAndroid:
		return "Android phone"
	case PlatformIOS:
		return "iPhone or iPad"
	case PlatformWeb:
		return "Web browser"
	}
	return "Device"
}

// EnsureNative finds or creates the device and installation of a native claim in the caller's transaction. An installation of
// another account, of another product or on a revoked device is refused; a known one is touched (version, platform text, last
// activity). A concurrent first sign-in with the same new installation ID loses on the primary key and is answered overloaded.
func EnsureNative(ctx context.Context, tx pgx.Tx, userID platform.ID, claim Claim, now time.Time) (deviceID platform.ID, err error) {
	devicePlatform, ok := MobilePlatform(claim.Platform)
	if !ok {
		return platform.ID{}, arc.InvalidArgument("installation.platform", "not_admitted")
	}
	var owner platform.ID
	var product string
	var revoked bool
	err = tx.QueryRow(ctx, `SELECT i.device_id, i.user_id, i.product_id, i.revoked_at IS NOT NULL OR d.revoked_at IS NOT NULL
FROM device.installation i JOIN device.device d ON d.device_id = i.device_id
WHERE i.installation_id = $1 FOR UPDATE OF i, d`, claim.InstallationID).Scan(&deviceID, &owner, &product, &revoked)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		deviceID = platform.NewID()
		if _, err = tx.Exec(ctx, `INSERT INTO device.device (device_id, user_id, display_name, platform, trust_level, remote_enabled, first_seen_at,
    last_seen_at, rev) VALUES ($1, $2, $3, $4, 1, false, $5, $5, 1)`, deviceID, userID, defaultName(devicePlatform), int16(devicePlatform), now); err != nil {
			return platform.ID{}, store.Sanitize("create a device", err)
		}
		if _, err = tx.Exec(ctx, `INSERT INTO device.installation (installation_id, device_id, user_id, product_id, app_version, platform, installed_at,
    last_active_at, rev) VALUES ($1, $2, $3, $4, $5, $6, $7, $7, 1)`, claim.InstallationID, deviceID, userID, claim.Product, claim.AppVersion,
			claim.Platform, now); err != nil {
			if errors.Is(store.Sanitize("create an installation", err), store.ErrConflict) {
				return platform.ID{}, arc.Unavailable()
			}
			return platform.ID{}, store.Sanitize("create an installation", err)
		}
		return deviceID, nil
	case err != nil:
		return platform.ID{}, store.Sanitize("find an installation", err)
	case owner != userID || product != claim.Product:
		return platform.ID{}, arc.PermissionDenied("installation")
	case revoked:
		return platform.ID{}, arc.CredentialRevoked()
	}
	if _, err = tx.Exec(ctx, `UPDATE device.installation SET app_version = $2, platform = $3, last_active_at = greatest(last_active_at, $4), rev = rev + 1
WHERE installation_id = $1`, claim.InstallationID, claim.AppVersion, claim.Platform, now); err != nil {
		return platform.ID{}, store.Sanitize("touch an installation", err)
	}
	if _, err = tx.Exec(ctx, "UPDATE device.device SET last_seen_at = greatest(last_seen_at, $2), rev = rev + 1 WHERE device_id = $1", deviceID, now); err != nil {
		return platform.ID{}, store.Sanitize("touch a device", err)
	}
	return deviceID, nil
}

// EnsureBrowser finds or creates the web device and installation of a browser's claimed installation ID for an account, in the
// caller's transaction: the live installation of that account with that claim, or a new device and installation (with an ID the
// center generates) when there is none, so a claim of another account or of a revoked device never links to it.
func EnsureBrowser(ctx context.Context, tx pgx.Tx, userID, claimed platform.ID, appVersion string, now time.Time) (deviceID, installationID platform.ID, err error) {
	if !isClaimText(appVersion) {
		return platform.ID{}, platform.ID{}, arc.InvalidArgument("installation.app_version", "pattern")
	}
	err = tx.QueryRow(ctx, `SELECT i.device_id, i.installation_id FROM device.installation i JOIN device.device d ON d.device_id = i.device_id
WHERE i.user_id = $1 AND i.client_installation_id = $2 AND i.revoked_at IS NULL AND d.revoked_at IS NULL FOR UPDATE OF i, d`, userID, claimed).
		Scan(&deviceID, &installationID)
	switch {
	case errors.Is(err, pgx.ErrNoRows):
		deviceID, installationID = platform.NewID(), platform.NewID()
		if _, err = tx.Exec(ctx, `INSERT INTO device.device (device_id, user_id, display_name, platform, trust_level, remote_enabled, first_seen_at,
    last_seen_at, rev) VALUES ($1, $2, $3, 6, 1, false, $4, $4, 1)`, deviceID, userID, defaultName(PlatformWeb), now); err != nil {
			return platform.ID{}, platform.ID{}, store.Sanitize("create a web device", err)
		}
		if _, err = tx.Exec(ctx, `INSERT INTO device.installation (installation_id, device_id, user_id, product_id, app_version, platform,
    client_installation_id, installed_at, last_active_at, rev) VALUES ($1, $2, $3, 'arcforges-web', $4, 'web', $5, $6, $6, 1)`,
			installationID, deviceID, userID, appVersion, claimed, now); err != nil {
			return platform.ID{}, platform.ID{}, store.Sanitize("create a web installation", err)
		}
		return deviceID, installationID, nil
	case err != nil:
		return platform.ID{}, platform.ID{}, store.Sanitize("find a web installation", err)
	}
	if _, err = tx.Exec(ctx, "UPDATE device.installation SET app_version = $2, last_active_at = greatest(last_active_at, $3), rev = rev + 1 WHERE installation_id = $1",
		installationID, appVersion, now); err != nil {
		return platform.ID{}, platform.ID{}, store.Sanitize("touch a web installation", err)
	}
	if _, err = tx.Exec(ctx, "UPDATE device.device SET last_seen_at = greatest(last_seen_at, $2), rev = rev + 1 WHERE device_id = $1", deviceID, now); err != nil {
		return platform.ID{}, platform.ID{}, store.Sanitize("touch a web device", err)
	}
	return deviceID, installationID, nil
}

// Installed is one live installation of a device (the contract's InstalledProduct).
type Installed struct {
	Product     string
	Version     string
	InstalledAt time.Time
}

// View is a device as the account sees it (the contract's DeviceView).
type View struct {
	DeviceID      platform.ID
	Name          string
	Platform      Platform
	Trust         int16
	RemoteEnabled bool
	RevokedAt     *time.Time
	Revision      int64
	FirstSeenAt   time.Time
	Installed     []Installed
}

// Querier is a transaction or a connection.
type Querier interface {
	Query(ctx context.Context, sql string, arguments ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, arguments ...any) pgx.Row
}

const viewColumns = "SELECT d.device_id, d.display_name, d.platform, d.trust_level, d.remote_enabled, d.revoked_at, d.rev, d.first_seen_at FROM device.device d "

func scanViews(rows pgx.Rows) ([]View, error) {
	defer rows.Close()
	var views []View
	for rows.Next() {
		var view View
		var devicePlatform int16
		if err := rows.Scan(&view.DeviceID, &view.Name, &devicePlatform, &view.Trust, &view.RemoteEnabled, &view.RevokedAt, &view.Revision,
			&view.FirstSeenAt); err != nil {
			return nil, err
		}
		view.Platform = Platform(devicePlatform)
		views = append(views, view)
	}
	return views, rows.Err()
}

// installed fills the live installations of the views.
func installed(ctx context.Context, q Querier, views []View) error {
	if len(views) == 0 {
		return nil
	}
	// The pool keeps no session state (exec mode), so an array parameter goes as text: the canonical UUIDs, cast in SQL.
	ids := make([]string, len(views))
	index := map[platform.ID]int{}
	for position, view := range views {
		ids[position] = view.DeviceID.String()
		index[view.DeviceID] = position
	}
	rows, err := q.Query(ctx, `SELECT device_id, product_id, app_version, installed_at FROM device.installation
WHERE device_id = ANY($1::uuid[]) AND revoked_at IS NULL ORDER BY installed_at, product_id`, ids)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var deviceID platform.ID
		var item Installed
		if err = rows.Scan(&deviceID, &item.Product, &item.Version, &item.InstalledAt); err != nil {
			return err
		}
		views[index[deviceID]].Installed = append(views[index[deviceID]].Installed, item)
	}
	return rows.Err()
}

// Get is one device of an account, or nil.
func Get(ctx context.Context, q Querier, userID, deviceID platform.ID) (*View, error) {
	rows, err := q.Query(ctx, viewColumns+"WHERE d.user_id = $1 AND d.device_id = $2", userID, deviceID)
	if err != nil {
		return nil, store.Sanitize("read a device", err)
	}
	views, err := scanViews(rows)
	if err != nil {
		return nil, store.Sanitize("read a device", err)
	}
	if len(views) == 0 {
		return nil, nil
	}
	if err = installed(ctx, q, views); err != nil {
		return nil, store.Sanitize("read a device", err)
	}
	return &views[0], nil
}

// List is one page of an account's live devices, oldest first. A browser's device is listed only while it has a live session
// (a browser that signed out or whose sessions expired drops out of the list; its row stays until the account's retention); a
// revoked device is not listed.
func List(ctx context.Context, db *store.DB, userID platform.ID, request page.Request, now time.Time) ([]View, string, error) {
	var views []View
	next := ""
	err := db.InTx(ctx, "list devices", store.TxOptions{ReadOnly: true}, func(ctx context.Context, tx pgx.Tx) error {
		views, next = nil, ""
		after, afterID := time.Unix(0, 0).UTC().Add(-100*365*24*time.Hour), platform.ID{}
		if request.After != nil {
			after, afterID = request.After.At, request.After.ID
		}
		rows, err := tx.Query(ctx, viewColumns+`WHERE d.user_id = $1 AND d.revoked_at IS NULL
    AND (d.platform <> 6 OR EXISTS (SELECT 1 FROM identity.session s WHERE s.device_id = d.device_id AND s.revoked_at IS NULL AND s.expires_at > $2
        AND (s.idle_expires_at IS NULL OR s.idle_expires_at > $2)))
    AND (d.first_seen_at, d.device_id) > ($3, $4)
ORDER BY d.first_seen_at, d.device_id
LIMIT $5`, userID, now, after, afterID, request.Limit+1)
		if err != nil {
			return err
		}
		if views, err = scanViews(rows); err != nil {
			return err
		}
		if len(views) > request.Limit {
			views = views[:request.Limit]
			last := views[len(views)-1]
			next = page.Encode(page.Devices, page.Cursor{At: last.FirstSeenAt, ID: last.DeviceID})
		}
		return installed(ctx, tx, views)
	})
	if err != nil {
		return nil, "", store.Sanitize("list devices", err)
	}
	return views, next, nil
}
